<?php
require_once __DIR__ . '/sesi.php'; wajibLogin();
require_once __DIR__ . '/tampilan.php';
$raw = $_GET['id'] ?? '';
$id = is_string($raw) && preg_match('/^[1-9][0-9]*$/D', $raw) ? filter_var($raw, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1, 'max_range' => 4294967295]]) : false;
if ($id === false) halamanError(400, 'ID informasi tidak valid', 'Gunakan ID berupa bilangan bulat positif pada alamat detail.');
require_once __DIR__ . '/koneksi.php';
try {
    // ID tervalidasi tetap diikat sebagai integer; validasi bukan pengganti prepare.
    $stmt = $db->prepare('SELECT i.*, p.nama AS penginput FROM informasi i JOIN pengguna p ON p.id = i.pengguna_id WHERE i.id = ?');
    $stmt->bind_param('i', $id); $stmt->execute(); $row = $stmt->get_result()->fetch_assoc();
} catch (mysqli_sql_exception $ex) { gagalDatabase($ex); }
if (!$row) halamanError(404, 'Informasi tidak ditemukan', 'Informasi dengan ID tersebut belum tersedia.');
awalHalaman($row['judul']); ?>
<main id="konten" class="container detail-page"><a class="back-link" href="daftar.php">← Kembali ke informasi</a><header class="detail-header"><span class="kind"><?= e(ucfirst($row['jenis'])) ?></span><h1><?= e($row['judul']) ?></h1><p><?= e($row['penyelenggara']) ?> <span aria-hidden="true">·</span> Diinput oleh <?= e($row['penginput']) ?></p></header><div class="detail-layout"><article class="detail-content"><?php if ($poster = posterAman($row['poster_url'] ?? null)): ?><img class="detail-poster" src="<?= e($poster) ?>" alt="Poster <?= e($row['judul']) ?>" loading="lazy"><?php endif; ?><section><span class="eyebrow">TENTANG PROGRAM</span><h2>Info program</h2><p class="preserve-lines"><?= e($row['deskripsi']) ?></p></section><section><span class="eyebrow">SEBELUM MENDAFTAR</span><h2>Persyaratan</h2><p class="preserve-lines"><?= e($row['persyaratan']) ?></p></section><?php if ($row['sumber_url']): ?><div class="import-source"><p>Sumber: <a href="<?= e($row['sumber_url']) ?>" target="_blank" rel="noopener noreferrer">Luar Kampus ↗</a> · Diambil <?= e(tanggal($row['diambil_pada'])) ?></p><p>Ringkasan ini berasal dari kalender publik. Detail di Luar Kampus meminta login. Biaya, pendanaan, dan ketentuan yang tidak tercantum perlu dicek di halaman sumber.</p></div><?php else: ?><div class="source-note"><p>Cek ketentuan lengkap di situs penyelenggara sebelum mendaftar.</p></div><?php endif; ?></article><aside class="summary-panel" aria-label="Ringkasan informasi"><div class="summary-top"><span class="eyebrow">JADWAL PENDAFTARAN</span><?php statusBadge($row['deadline'], $row['mulai'] ?? null); ?></div><p class="muted">Batas pendaftaran</p><h2><?= e(tanggal($row['deadline'])) ?></h2><dl><?php if ($row['mulai']): ?><div><dt>Mulai pendaftaran</dt><dd><?= e(tanggal($row['mulai'])) ?></dd></div><?php endif; ?><?php if ($row['lokasi']): ?><div><dt>Lokasi</dt><dd><?= e($row['lokasi']) ?></dd></div><?php endif; ?><div><dt>Penyelenggara</dt><dd><?= e($row['penyelenggara']) ?></dd></div><?php if ($row['jenis'] === 'beasiswa'): ?><div><dt>Cakupan pendanaan</dt><dd><?= e($row['pendanaan'] ?? 'Belum tercantum di sumber') ?></dd></div><?php else: ?><div><dt>Biaya pendaftaran</dt><dd><?= e(biayaLabel($row['biaya'])) ?></dd></div><div><dt>Bentuk peserta</dt><dd><?= e($row['peserta'] ?? 'Belum tercantum di sumber') ?></dd></div><?php endif; ?><div><dt>Diinput oleh</dt><dd><?= e($row['penginput']) ?></dd></div><div><dt>Ditambahkan</dt><dd><?= e(tanggal($row['dibuat_pada'])) ?></dd></div></dl>
<?php if (!masihBuka($row['deadline'])): ?><p class="closed-note">Deadline telah lewat. Informasi ini tetap tersedia sebagai arsip.</p><?php endif; ?>
<?php $scheme = strtolower((string)parse_url($row['url_pendaftaran'], PHP_URL_SCHEME)); if (filter_var($row['url_pendaftaran'], FILTER_VALIDATE_URL) && in_array($scheme, ['http','https'], true)): ?><a class="button full" href="<?= e($row['url_pendaftaran']) ?>" target="_blank" rel="noopener noreferrer"><?= $row['sumber_url'] ? 'Buka info di Luar Kampus' : 'Ke situs pendaftaran' ?> <span aria-hidden="true">↗</span></a><p class="panel-note"><?= $row['sumber_url'] ? 'Halaman sumber dibuka di tab baru.' : 'Situs penyelenggara dibuka di tab baru.' ?></p><?php else: ?><p class="closed-note">Tautan penyelenggara belum tersedia.</p><?php endif; ?></aside></div></main>
<?php akhirHalaman(); ?>
